  Map<Long,Row> invoices=index(rows(Bill.class));BigDecimal revenue=validPayments().stream().filter(p->paymentMatches(p,f,invoices)).map(p->allocated(p,invoices.get(p.id("billId")),"laboratoryCharge")).reduce(BigDecimal.ZERO,BigDecimal::add);
  List<Metric> metrics=new ArrayList<>(List.of(metric("Test requests",list.size()),metric("Pending",count(list,"PENDING")+count(list,"SCHEDULED")),metric("Processing",count(list,"PROCESSING")),metric("Completed",count(list,"COMPLETED")),metric("Awaiting results",list.stream().filter(r->!r.status().equals("CANCELLED")&&r.text("result").isEmpty()).count())));
